"use client";
import { useState } from "react";
import { TextMorph } from "@/components/application/animations/expanded/typography/text-morph";

export default function Example() {
  const [text, setText] = useState("Running Shoes");
  return <>
    <input aria-label="Morph text" value={text} onChange={event => setText(event.target.value)} />
    <TextMorph text={text}
      duration={0.65}
      rapidInputThreshold={90}
    />
  </>;
}

